import zipfile,xml.etree.ElementTree as E,pathlib
for p in sorted(pathlib.Path('docs/kiertokirjeet').glob('*.docx')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  r=E.fromstring(z.read('word/document.xml'))
  ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
  for para in r.findall('.//w:p',ns):
   print(''.join(para.itertext()) if False else ''.join(t.text or '' for t in para.findall('.//w:t',ns)))
for p in sorted(pathlib.Path('docs/liitteet').glob('*.xlsx')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
  strings=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   strings=[''.join(t.itertext()) for t in E.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',ns)]
  for f in z.namelist():
   if f.startswith('xl/worksheets/sheet') and f.endswith('.xml'):
    print(f)
    for row in E.fromstring(z.read(f)).findall('.//m:row',ns):
     cells=[]
     for c in row.findall('m:c',ns):
      v=c.find('m:v',ns)
      val=v.text if v is not None else ''.join(t.text or '' for t in c.findall('.//m:t',ns))
      if c.get('t')=='s':val=strings[int(val)]
      cells.append(c.get('r')+'='+str(val))
     print(' | '.join(cells))
PY"

